insert into public.posts (id,thread_id,author_handle,body,quote_post_id,created_at) values
  (2301,23,'ford','Friday, Nov. 6 at 6 p.m. at Ford. The schedule says Wear Blue, so dig out the blue stuff. Who''s tailgating?',null,now()-interval '900 minutes'),
  (2302,23,'snider','In. We''re usually on the Boulevard near Dallas Hall by 3.',null,now()-interval '840 minutes'),
  (2303,23,'grace','Friday kick means I''m leaving work at 2 and not apologizing.',null,now()-interval '610 minutes'),
  (2401,24,'cox','The Nov. 14 game still says TBA on the official schedule. Anyone heard anything? Trying to book a hotel for family.',null,now()-interval '1500 minutes'),
  (2402,24,'hank','Nothing yet. TV windows usually get set a week or two out.',null,now()-interval '1380 minutes'),
  (2403,24,'cox','Thanks. Booking the refundable rate then.',null,now()-interval '1300 minutes'),
  (2501,25,'dallas','11 a.m. kick on ESPN2 and I''m not making the trip. Where are people watching?',null,now()-interval '700 minutes'),
  (2502,25,'belle','Anywhere near campus with a patio. Get there early, 11 a.m. games fill up fast.',null,now()-interval '650 minutes'),
  (2503,25,'mike','Snider Plaza has a couple of spots that put it on every screen.',null,now()-interval '560 minutes'),
  (2601,26,'peruna','First real look at this roster. What does a good November look like to you?',null,now()-interval '2000 minutes'),
  (2602,26,'ray','Defense that travels. If they guard, the offense will come.',null,now()-interval '1900 minutes'),
  (2603,26,'hank','I just want Moody loud from the opening tip.',null,now()-interval '1700 minutes'),
  (2604,26,'peruna','That part is on us.',null,now()-interval '1650 minutes'),
  (2701,27,'grace','Making a point of getting to more women''s games this year. Who wants to sit together?',null,now()-interval '2600 minutes'),
  (2702,27,'belle','Count me in. Let''s fill a section.',null,now()-interval '2400 minutes'),
  (2801,28,'band','I watch serve receive first. When the passing is calm, everything else follows.',null,now()-interval '800 minutes'),
  (2802,28,'ray','Same. Plus the block. Fun team to watch in person.',null,now()-interval '720 minutes'),
  (2803,28,'band','Agreed. I need to get to more home matches.',null,now()-interval '690 minutes'),
  (2901,29,'snider','Trying to get to a match before the season wraps. Anyone want to go together?',null,now()-interval '1100 minutes'),
  (2902,29,'mike','Going. Bringing a couple of friends who have never been to a match.',null,now()-interval '980 minutes'),
  (2903,29,'snider','Good. Sit near the student side, it''s the most fun.',null,now()-interval '940 minutes'),
  (3001,30,'belle','Not enough talk about this team on here. Favorite moment of the season so far?',null,now()-interval '3200 minutes'),
  (3002,30,'grace','Any match under the lights at Westcott. Great atmosphere.',null,now()-interval '3000 minutes'),
  (3101,31,'dallas','Friend swims for a club team and wants to go to a meet. Never been. Tips?',null,now()-interval '4300 minutes'),
  (3102,31,'ford','It moves fast. Grab a heat sheet and pick a lane to follow.',null,now()-interval '4100 minutes'),
  (3103,31,'dallas','Heat sheet. Got it, thanks.',null,now()-interval '4000 minutes'),
  (3201,32,'cox','Trying to learn the college golf format. How do team scores work?',null,now()-interval '5200 minutes'),
  (3202,32,'hank','Usually five play and the best four scores count each round. Makes every shot matter more than you''d think.',null,now()-interval '5000 minutes'),
  (3301,33,'mike','Going to my first dual match. How does scoring work again?',null,now()-interval '6100 minutes'),
  (3302,33,'peruna','Doubles point first, then six singles. First team to four wins.',null,now()-interval '5900 minutes'),
  (3303,33,'mike','Simple enough. Thanks!',null,now()-interval '5850 minutes'),
  (3401,34,'grace','Do people go out to cross country meets? Seems like a fun morning.',null,now()-interval '7000 minutes'),
  (3402,34,'band','Bring a coffee and walk the course. You can see runners in three or four spots.',null,now()-interval '6800 minutes'),
  (3501,35,'snider','Saw a photo of the eight on the water and now I want to understand rowing. Where do I start?',null,now()-interval '7600 minutes'),
  (3502,35,'cox','Watch a 2,000-meter race on video first. Once you see the boats move together it clicks.',null,now()-interval '7400 minutes'),
  (3601,36,'hank','Never been to an equestrian meet. Is it head to head?',null,now()-interval '8400 minutes'),
  (3602,36,'belle','Riders from each team draw the same horse and compete on it, so it''s rider against rider.',null,now()-interval '8200 minutes'),
  (3603,36,'hank','That''s a great format.',null,now()-interval '8150 minutes'),
  (3701,37,'ray','Post your best parking strategy for Ford. I''ll go first: get there early and walk.',null,now()-interval '9000 minutes'),
  (3702,37,'mike','DART if you can. No parking at all.',null,now()-interval '8800 minutes'),
  (3703,37,'ray','Underrated answer.',null,now()-interval '8700 minutes'),
  (3801,38,'staff','We''re planning the November practice reports. What do you want more of? (Sample post for this concept.)',null,now()-interval '4800 minutes'),
  (3802,38,'peruna','Position battles and who''s getting reps with the ones.',null,now()-interval '4600 minutes'),
  (3803,38,'ford','Injury context when there is any, but only what''s public.',null,now()-interval '4500 minutes'),
  (3804,38,'staff','Noted on both. Only what we can share, always.',null,now()-interval '4400 minutes'),
  (3901,39,'dre','Pick one thing you want broken down after Syracuse. Most votes wins. (Sample post for this concept.)',null,now()-interval '1900 minutes'),
  (3902,39,'ray','Third-down defense.',null,now()-interval '1800 minutes'),
  (3903,39,'pete','Red zone offense, please.',null,now()-interval '1750 minutes'),
  (4001,40,'dallas','Want to change my board name. Where is that?',null,now()-interval '10000 minutes'),
  (4002,40,'staff','Account page, under Profile. Your old posts update too.',null,now()-interval '9900 minutes'),
  (4101,41,'snider','First season with student tickets. Where''s the loudest spot?',null,now()-interval '2300 minutes'),
  (4102,41,'mike','Behind the basket. Get there before warmups.',null,now()-interval '2200 minutes'),
  (4103,41,'band','Stand near the band if you want to learn the chants fast.',null,now()-interval '2100 minutes'),
  (4104,41,'snider','Behind the basket near the band it is.',null,now()-interval '2050 minutes'),
  (4105,41,'grace','Wear red. You''ll see why.',null,now()-interval '1990 minutes'),
  (4201,42,'ray','Thinking about one road trip once the conference schedule is out. Anyone done this before?',null,now()-interval '3900 minutes'),
  (4202,42,'pete','Pick a city you''d visit anyway and make a weekend of it.',null,now()-interval '3800 minutes'),
  (4301,43,'belle','Idea: everyone brings one person who has never been to a women''s game. Who''s in?',null,now()-interval '4700 minutes'),
  (4302,43,'grace','In. Bringing my sister.',null,now()-interval '4600 minutes'),
  (4303,43,'cox','In. Bringing two coworkers.',null,now()-interval '4500 minutes'),
  (4304,43,'hank','Count me and my kids.',null,now()-interval '4400 minutes'),
  (4401,44,'grace','Where do you like to sit for volleyball? End line or sideline?',null,now()-interval '5600 minutes'),
  (4402,44,'ray','End line, behind the server. You see every serve move.',null,now()-interval '5500 minutes'),
  (4403,44,'belle','Sideline up high so you can follow the whole rally.',null,now()-interval '5400 minutes'),
  (4501,45,'band','Let''s get a few chants going this season. Suggestions?',null,now()-interval '6600 minutes'),
  (4502,45,'mike','Anything short and loud between serves.',null,now()-interval '6500 minutes'),
  (4503,45,'peruna','Keep it friendly. Families are there too.',null,now()-interval '6400 minutes'),
  (4504,45,'band','Agreed. Short, loud and friendly.',null,now()-interval '6300 minutes'),
  (4505,45,'ford','I''ll bring a cowbell. Kidding. Mostly.',null,now()-interval '6200 minutes'),
  (4506,45,'grace','Please don''t.',null,now()-interval '6150 minutes'),
  (4601,46,'cox','Taking my nephew to his first women''s soccer match. Any tips?',null,now()-interval '7300 minutes'),
  (4602,46,'belle','Bring a blanket on cold nights and stay for the end. Players often come over to the stands.',null,now()-interval '7200 minutes')
