-- SMU+ PROPOSED_9 (NOT RUN): more sample threads so The Mustang Board's real counts aren't all 0s and 1s.
-- Fictional fans and opinions only. No scores, stats or quotes are invented; the dates and kickoff details are from the official 2026 schedules already on the site.
-- Thread ids 23-46 follow seed.sql's convention (id < 1000 with an author_handle), so a seed.sql re-run deletes them unless the matching entries
-- (PROPOSED_9_more_board_threads.data.js.txt) are added to assets/data.js and seed.sql is rebuilt. Add them to data.js too, so demo mode shows the same boards.
-- reply_count and last_post_at are set from the real rows at the end. Safe to re-run (on conflict do nothing).
begin;
on conflict (id) do nothing;
on conflict (id) do nothing;
-- Set counts from the real rows (the post trigger counts a multi-row insert's own rows, so don't rely on it here).
update public.threads t
   set reply_count = greatest(0, (select count(*) from public.posts p where p.thread_id = t.id) - 1),
       last_post_at = coalesce((select max(p.created_at) from public.posts p where p.thread_id = t.id), t.last_post_at)
 where t.id between 23 and 46;
commit;
